package com.example.rokidgeminisecretary;
import android.content.*;import org.json.*;import java.io.*;import java.util.*;
final class RecordAnchors {
 static String photoId(String id)throws IOException{if(id==null||!id.matches("[0-9]{13}-[a-f0-9-]{36}"))throw new IOException("写真の参照が不正です");return id;}
 static JSONArray search(Context c,String query,JSONArray issues)throws Exception{JSONArray meetings=MeetingAudioStore.list(c),out=new JSONArray();int bytes=0;for(int i=0;i<Math.min(20,meetings.length());i++){JSONObject meeting=meetings.getJSONObject(i);File folder=MeetingAudioStore.folder(c,meeting.getString("id"));JSONArray parts=MeetingAudioStore.meta(folder).getJSONArray("parts");if(parts.length()>720){issues.put("長い会議の文字起こしは対象外");continue;}long at=0;for(int first=0;first<parts.length()&&first<180;first+=6){long start=at;for(int j=first;j<Math.min(first+6,parts.length());j++)at+=Math.max(0,parts.getJSONObject(j).optLong("bytes"))/32;File f=new File(folder,String.format(Locale.US,"transcript-%04d.gcm",first));if(!f.isFile())continue;if(f.length()>100000){issues.put("大きい文字起こし区間は対象外");continue;}bytes+=f.length();if(bytes>2000000){issues.put("文字起こしの検索は合計2MBまで");return out;}try{String text=new String(RecorderPhotoStore.read(f),"UTF-8");if(RecordSearchPolicy.matches(meeting.optString("title")+" "+text,query))out.put(UnifiedRecords.item("meeting",meeting.getString("id"),meeting.optLong("startedAt")+start,meeting.optString("title","会議")+" / 約"+start/1000+"秒の文字起こし",text).put("anchorMs",start).put("approximate",true));}catch(Exception e){issues.put("文字起こし区間を取得できません");}}}return out;}
 static JSONObject target(Context c,String id,long ms)throws Exception{if(ms<0||ms>7260000)throw new IOException("再生位置が不正です");JSONArray parts=MeetingAudioStore.meta(MeetingAudioStore.folder(c,id)).getJSONArray("parts");if(parts.length()<1||parts.length()>720)throw new IOException("音声区間を確認してください");long total=0;for(int i=0;i<parts.length();i++)total+=Math.max(0,parts.getJSONObject(i).optLong("bytes"))/32;if(total<1||total>7260000)throw new IOException("音声の長さを確認できません");long at=0,safe=Math.min(ms,total-1);for(int i=0;i<parts.length();i++){long length=Math.max(0,parts.getJSONObject(i).optLong("bytes"))/32;if(safe<at+length)return new JSONObject().put("id",id).put("parts",parts.length()).put("part",i).put("offsetMs",safe-at).put("anchorMs",safe).put("durationMs",total);at+=length;}throw new IOException("再生位置を確認できません");}
 private RecordAnchors(){}
}
